-- Product suite: discovery, retention, communication, commerce and operations
create table if not exists public.saved_videos(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,video_id uuid not null references public.videos(id) on delete cascade,created_at timestamptz not null default now(),unique(user_id,video_id));
create table if not exists public.watch_progress(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,video_id uuid not null references public.videos(id) on delete cascade,position_seconds int not null default 0,duration_seconds int not null default 0,updated_at timestamptz not null default now(),unique(user_id,video_id));
create table if not exists public.live_reminders(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,live_id uuid not null references public.live_sessions(id) on delete cascade,created_at timestamptz not null default now(),unique(user_id,live_id));
create table if not exists public.live_chat_messages(id uuid primary key default gen_random_uuid(),live_id uuid not null references public.live_sessions(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,content text not null check(char_length(content) between 1 and 500),created_at timestamptz not null default now());
create table if not exists public.direct_messages(id uuid primary key default gen_random_uuid(),sender_id uuid not null references public.profiles(id) on delete cascade,recipient_id uuid not null references public.profiles(id) on delete cascade,content text not null check(char_length(content) between 1 and 2000),read_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.coupons(id uuid primary key default gen_random_uuid(),creator_id uuid references public.creators(id) on delete cascade,code text not null unique,discount_percent int not null check(discount_percent between 1 and 100),starts_at timestamptz,ends_at timestamptz,max_uses int,uses int not null default 0,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.content_bundles(id uuid primary key default gen_random_uuid(),creator_id uuid not null references public.creators(id) on delete cascade,title text not null,description text,price numeric(10,2) not null check(price>=0),is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.bundle_videos(bundle_id uuid not null references public.content_bundles(id) on delete cascade,video_id uuid not null references public.videos(id) on delete cascade,primary key(bundle_id,video_id));
create table if not exists public.ppv_wishlist(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,video_id uuid not null references public.videos(id) on delete cascade,created_at timestamptz not null default now(),unique(user_id,video_id));
create table if not exists public.creator_goals(id uuid primary key default gen_random_uuid(),creator_id uuid not null references public.creators(id) on delete cascade,title text not null,metric text not null check(metric in('revenue','subscribers')),target numeric not null check(target>0),starts_at date not null default current_date,ends_at date,is_active boolean not null default true);
create table if not exists public.support_tickets(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),subject text not null,message text not null,status text not null default 'open' check(status in('open','in_progress','resolved','closed')),priority text not null default 'normal' check(priority in('low','normal','high')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.premieres(id uuid primary key default gen_random_uuid(),video_id uuid not null unique references public.videos(id) on delete cascade,creator_id uuid not null references public.creators(id) on delete cascade,starts_at timestamptz not null,status text not null default 'scheduled' check(status in('scheduled','live','ended','cancelled')),created_at timestamptz not null default now());
create table if not exists public.premiere_reminders(id uuid primary key default gen_random_uuid(),premiere_id uuid not null references public.premieres(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),unique(premiere_id,user_id));
create table if not exists public.live_clips(id uuid primary key default gen_random_uuid(),live_id uuid not null references public.live_sessions(id) on delete cascade,creator_id uuid not null references public.creators(id) on delete cascade,title text,start_seconds int not null,end_seconds int not null,video_url text,created_at timestamptz not null default now(),check(end_seconds>start_seconds));
do $$ begin alter table public.saved_videos enable row level security; alter table public.watch_progress enable row level security; alter table public.live_reminders enable row level security; alter table public.live_chat_messages enable row level security; alter table public.direct_messages enable row level security; alter table public.ppv_wishlist enable row level security; alter table public.support_tickets enable row level security; alter table public.premiere_reminders enable row level security; exception when others then null; end $$;
create policy "own saved" on public.saved_videos for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own progress" on public.watch_progress for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own reminders" on public.live_reminders for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "live chat read" on public.live_chat_messages for select to authenticated using(true); create policy "live chat send" on public.live_chat_messages for insert to authenticated with check(user_id=auth.uid());
create policy "own messages" on public.direct_messages for select to authenticated using(sender_id=auth.uid() or recipient_id=auth.uid()); create policy "send messages" on public.direct_messages for insert to authenticated with check(sender_id=auth.uid());
create policy "own wishlist" on public.ppv_wishlist for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own tickets" on public.support_tickets for select to authenticated using(user_id=auth.uid()); create policy "open tickets" on public.support_tickets for insert to authenticated with check(user_id=auth.uid());
create policy "own premiere reminders" on public.premiere_reminders for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create index if not exists dm_people_idx on public.direct_messages(sender_id,recipient_id,created_at); create index if not exists progress_user_idx on public.watch_progress(user_id,updated_at desc); create index if not exists live_chat_idx on public.live_chat_messages(live_id,created_at);
